import{F as e,_ as t,f as n,h as r,j as i,n as a}from"./chunks/shared.rYHlazZf.js";var o=JSON.parse(`{"title":"Organiser les automatisations","description":"","frontmatter":{"title":"Organiser les automatisations","docId":"user.automations.index","translationKey":"user.automations.index","locale":"fr","audience":"user","featureStatus":"available","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"08bb26a20687b58094e908a4e8395abeae3b9adc3932c86d9c3b08f5ebbf8ce3","translationRevision":"21418d5e43873d05197f9291010893eed584cc38ca18832ec1d3ad859f59c1a4","order":10},"headers":[],"relativePath":"fr/user/automations/index.md","filePath":"fr/user/automations/index.md","lastUpdated":1795727787000}`),s={name:`fr/user/automations/index.md`};function c(a,o,s,c,l,u){let d=e(`DemoFrame`);return i(),n(`div`,null,[o[0]||=r(`<h1 id="organize-automations" tabindex="-1">Organiser les automatisations <a class="header-anchor" href="#organize-automations" aria-label="Permalink to “Organiser les automatisations”">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">Objectif et prérequis <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to “Objectif et prérequis”">​</a></h2><p>Construire une petite bibliothèque compréhensible qui réagit aux événements LIVE. Il faut un hôte de bureau fonctionnel. Une véritable <a href="./../live/connections.html">connexion LIVE</a> est nécessaire pour valider les événements distants ; les actions de plugins nécessitent aussi un plugin et un service prêts.</p><h2 id="understand-the-library" tabindex="-1">Comprendre la bibliothèque <a class="header-anchor" href="#understand-the-library" aria-label="Permalink to “Comprendre la bibliothèque”">​</a></h2><p>Une <strong>Action</strong> est une opération configurée réutilisable, comme écrire une ligne de journal ou jouer un son. Un <strong>Event</strong> choisit un déclencheur, des filtres, un délai et des actions liées. Un profil regroupe les définitions d’un usage ; un seul ensemble de profil est actif à la fois. Les <a href="./variables.html">Variables</a> d’exécution fournissent des valeurs réutilisables par plusieurs actions.</p><ol><li>Ouvrez <strong>Automations</strong> et confirmez le profil actif avant toute modification. Recherchez séparément dans Events et Actions pour savoir quel type d’enregistrement vous sélectionnez.</li><li>Commencez par la <a href="./first-rule.html">première règle de journalisation</a>. Créez son action, puis un événement qui la référence.</li><li>Choisissez un déclencheur pris en charge par l’hôte actuel. Utilisez le sélecteur de champs pour ajouter des filtres adaptés. Plusieurs conditions restreignent les correspondances ; elles ne modifient pas la charge utile entrante.</li><li>Définissez un délai et sa portée. Un délai global limite la règle pour tous les spectateurs ; un délai par utilisateur suit chaque spectateur séparément.</li><li>Reliez les actions voulues dans l’ordre. Le mode normal exécute la liste choisie ; le mode aléatoire y sélectionne une action. Une action de délai reporte les actions suivantes sans ralentir l’ingestion LIVE.</li><li>Enregistrez, examinez les changements de définition affichés, puis activez explicitement les enregistrements à exécuter. Consultez l’historique pour le nom de l’action, son résultat et son erreur.</li></ol><p>Toute comparaison accepte une liste de valeurs au lieu d&#39;une seule. La combinaison par défaut est « au moins un » : la condition est remplie quand au moins une valeur correspond. Passez le quantificateur à « tous » quand chaque valeur doit correspondre — avec « n&#39;est pas », cela se lit « n&#39;est aucun de ». Une condition peut aussi nommer un alias de capture : la valeur gagnante est alors disponible pour les modèles d&#39;action sous la forme <code>{{ match.&lt;alias&gt; }}</code> (ou <code>{{ match.&lt;position&gt; }}</code> sans alias). Sous les conditions toujours requises, vous pouvez ajouter jusqu&#39;à quatre <strong>alternatives</strong> : des groupes dont toutes les conditions doivent être remplies, et un seul groupe suffit pour déclencher l&#39;événement.</p><p>Les tests peuvent exécuter les effets configurés. Lisez la liste d’actions sélectionnée avant d’appuyer sur <strong>Test</strong> ou de déclencher un événement, surtout pour l’audio, HTTP, les points et les opérations de plugins. Utilisez la journalisation pendant l’apprentissage.</p><h2 id="expected-result-and-status" tabindex="-1">Résultat attendu et état <a class="header-anchor" href="#expected-result-and-status" aria-label="Permalink to “Résultat attendu et état”">​</a></h2><p>L’édition locale, l’exécution, les modèles, les profils et l’historique sont disponibles. Les déclencheurs de plugins apparaissent uniquement lorsque le plugin correspondant est installé et activé. L’activation dépend de la surface et des valeurs enabled examinées ; vérifiez événements et actions avant confirmation. Le panneau <strong>Changes</strong> de Events/Actions est une <a href="./../cloud/changes.html">comparaison de référence locale</a>, pas un téléversement automatique vers Cloud.</p><h2 id="recovery" tabindex="-1">Récupération <a class="header-anchor" href="#recovery" aria-label="Permalink to “Récupération”">​</a></h2><p>En l’absence d’exécution, vérifiez dans cet ordre le profil actif, les états d’activation, le déclencheur, les filtres, le délai et les actions manquantes. En cas de conflit de révision, lisez la définition actuellement enregistrée et examinez-la à nouveau. N’écrasez pas aveuglément la mise à jour d’une autre personne. Exportez un <a href="./templates.html">profil</a> fonctionnel avant des modifications étendues.</p><h2 id="operational-details" tabindex="-1">Détails de fonctionnement <a class="header-anchor" href="#operational-details" aria-label="Permalink to “Détails de fonctionnement”">​</a></h2><p>Avant import ou changement de profil, lisez <a href="./templates.html#operational-details">l’activation par surface</a>. Le changement peut réactiver des membres désactivés individuellement. Le cooldown est en mémoire, limité à 24 heures ; les spectateurs sans uniqueId partagent un contexte anonyme. À 8 192 clés conservées, la table est vidée : surcharge ou redémarrage peuvent autoriser des exécutions supplémentaires. Ce n’est ni quota durable ni garantie de replay.</p><p>Essayez interactivement avant de toucher à votre vraie configuration :</p>`,15),t(d,{scenario:`automation`,locale:`fr`,panel:`automation`,title:`Essayez l'espace des automatisations`}),o[1]||=r(`<h2 id="command-line-operations" tabindex="-1">Opérations en ligne de commande <a class="header-anchor" href="#command-line-operations" aria-label="Permalink to “Opérations en ligne de commande”">​</a></h2><p>Chaque opération de ce guide est aussi disponible depuis la CLI — hors ligne, scriptable et adaptée aux agents. Les lignes d&#39;usage sont la syntaxe du parseur et restent en anglais dans toutes les langues.</p><table tabindex="0"><thead><tr><th>Commande</th><th>Résumé</th></tr></thead><tbody><tr><td><code>tiktools automation list [--kind event&amp;#124;action&amp;#124;all]</code></td><td>lister les règles d&#39;automatisation</td></tr><tr><td><code>tiktools automation context [--event-type t]</code></td><td>contexte de modèle disponible pour les règles</td></tr><tr><td><code>tiktools automation get &lt;id&gt; [--kind event&amp;#124;action]</code></td><td>lire une règle</td></tr><tr><td><code>tiktools automation create --record json [--kind event&amp;#124;action]</code></td><td>créer une règle</td></tr><tr><td><code>tiktools automation update &lt;id&gt; --record json [--kind event&amp;#124;action]</code></td><td>mettre à jour une règle</td></tr><tr><td><code>tiktools automation delete &lt;id&gt; [--kind event&amp;#124;action]</code></td><td>supprimer une règle <strong>destructif</strong></td></tr><tr><td><code>tiktools automation enable &lt;id&gt; [--kind event&amp;#124;action]</code></td><td>activer une règle</td></tr><tr><td><code>tiktools automation disable &lt;id&gt; [--kind event&amp;#124;action]</code></td><td>désactiver une règle</td></tr><tr><td><code>tiktools automation test (--id &lt;id&gt; &amp;#124; --record json) [--kind event&amp;#124;action] [--trigger t] [--event json]</code></td><td>tester une règle à blanc contre un événement d&#39;exemple</td></tr><tr><td><code>tiktools automation fire --trigger &lt;type&gt; [--event json] [--record json]</code></td><td>déclencher un déclencheur manuellement</td></tr><tr><td><code>tiktools automation moderation-penalty --points &lt;delta&gt;</code></td><td>appliquer une pénalité de modération en points</td></tr></tbody></table><table tabindex="0"><thead><tr><th>Commande</th><th>Résumé</th></tr></thead><tbody><tr><td><code>tiktools workflow list</code></td><td>lister les graphes de workflow enregistrés</td></tr><tr><td><code>tiktools workflow get &lt;id&gt;</code></td><td>lire un graphe</td></tr><tr><td><code>tiktools workflow save --record json</code></td><td>créer ou remplacer un graphe</td></tr><tr><td><code>tiktools workflow delete &lt;id&gt;</code></td><td>supprimer un graphe <strong>destructif</strong></td></tr><tr><td><code>tiktools workflow enable &lt;id&gt;</code></td><td>activer un graphe</td></tr><tr><td><code>tiktools workflow disable &lt;id&gt;</code></td><td>désactiver un graphe</td></tr></tbody></table><p>Consultez la <a href="./../../developer/cli.html">référence complète des commandes</a> pour les conventions, la sortie JSON et les marqueurs d’opérations destructives.</p>`,5)])}var l=a(s,[[`render`,c]]);export{o as __pageData,l as default};